// 1. Library Source Code (libutil.c)
// Compile with: gcc -shared -fPIC libutil.c -o libutil.so
int shared_operation(int x) {
    return x * x;
}

// 2. Client Runtime Linking (POSIX/dlopen)
// Dynamic loading at runtime
void *handle = dlopen("libutil.so", RTLD_LAZY);

if (!handle) { /* Log error, return */ }

// Define function signature
typedef int (*math_func)(int);

// Retrieve symbol
math_func op = (math_func)dlsym(handle, "shared_operation");

if (op) {
    int result = op(7);
}

dlclose(handle);

// 3. Client Runtime Linking (Windows/LoadLibrary)
HMODULE hLib = LoadLibrary("libutil.dll");

if (hLib == NULL) { /* Handle error */ }

typedef int (*FuncPtr)(int);
FuncPtr op = (FuncPtr)GetProcAddress(hLib, "shared_operation");

if (op) {
    int result = op(7);
}

FreeLibrary(hLib);
